    ["RAM", "ram_percent"],
    ["Disk", "disk_percent"]
];

const messages = fields
    .filter(([, key]) => typeof device.metrics[key] === "number")
    .map(([label, key]) => ({
        topic: label,
        payload: device.metrics[key],
        timestamp
    }));

return [messages];

